const $=id=>document.getElementById(id);
const data=window.CHANGES;
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const pretty=s=>s.toLocaleLowerCase('pt-BR').replace(/(^|[\s-])\p{L}/gu,c=>c.toLocaleUpperCase('pt-BR'));
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const query=(name,city)=>`${name}, ${city}, Rio Grande do Norte, Brasil`;
const maps=(name,city)=>'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(query(name,city));
const route=g=>'https://www.google.com/maps/dir/?api=1&origin='+encodeURIComponent(query(g.from,g.city))+'&destination='+encodeURIComponent(query(g.to,g.city));
for(const city of [...new Set(data.map(g=>g.city))].sort((a,b)=>a.localeCompare(b,'pt-BR'))) $('city').add(new Option(pretty(city),city));
function zones(){const old=$('zone').value;$('zone').replaceChildren(new Option('Todas as zonas',''));for(const z of [...new Set(data.filter(g=>!$('city').value||g.city===$('city').value).map(g=>g.zone))].sort((a,b)=>+a-+b))$('zone').add(new Option('Zona '+z,z));if([...$('zone').options].some(o=>o.value===old))$('zone').value=old;}
function filtered(){const city=$('city').value,zone=$('zone').value,s=$('section').value.trim();return data.filter(g=>(!city||g.city===city)&&(!zone||g.zone===zone)&&(!s||g.sections.includes(Number(s))));}
let visibleLimit=10;
function render(reset=true){if(reset)visibleLimit=10;const groups=filtered(),section=$('section').value.trim(),n=groups.reduce((sum,g)=>sum+(section?1:g.sections.length),0);$('count').textContent=groups.length?`${n} ${n===1?'seção encontrada':'seções encontradas'}`:'Nenhuma alteração encontrada';
const params=new URLSearchParams();if($('city').value)params.set('cidade',$('city').value);if($('zone').value)params.set('zona',$('zone').value);if(section)params.set('secao',section);history.replaceState(null,'',location.pathname+(params.size?'?'+params.toString():''));
$('more-results').innerHTML=groups.length>visibleLimit?`<p>Mostrando ${Math.min(visibleLimit,groups.length)} de ${groups.length} mudanças de local</p><button type="button" id="show-more">Mostrar mais mudanças ↓</button>`:'';
if(!groups.length){$('results').innerHTML='<div class="empty"><h3>Sua seção não aparece nesta lista.</h3><p>Isso não confirma que o local permaneceu igual. Confira a cidade, a zona e a seção e consulte seu endereço atualizado no e-Título ou no site do TSE.</p><a href="https://www.tse.jus.br/servicos-eleitorais/autoatendimento-eleitoral#/atendimento-eleitor/onde-votar" target="_blank" rel="noopener">Confirmar no TSE ↗</a></div>';return;}
$('results').innerHTML=groups.slice(0,visibleLimit).map(g=>`<article class="card"><div class="card-head"><h3>${esc(pretty(g.city))}</h3><span class="zone">Zona ${esc(g.zone)}</span></div><div class="places"><div><span class="place-label">LOCAL ANTERIOR · 1º TURNO</span><p class="place-name">${esc(g.from)}</p><a class="maps-link" target="_blank" rel="noopener" href="${maps(g.from,g.city)}">Buscar local anterior no Maps ↗</a></div><span class="arrow" aria-hidden="true">→</span><div class="destination"><span class="place-label">NOVO LOCAL · 2º TURNO</span><p class="place-name">${esc(g.to)}</p><a class="maps-link" target="_blank" rel="noopener" href="${maps(g.to,g.city)}">Buscar novo local no Maps ↗</a></div></div><div class="card-foot"><div class="sections"><strong>Seções:</strong> ${g.sections.map(s=>`<span class="section${section&&Number(section)===s?' match':''}">${s}</span>`).join(' ')}</div><div class="card-actions"><button type="button" data-share="${data.indexOf(g)}">Compartilhar</button><a class="route" href="${route(g)}" target="_blank" rel="noopener" title="Busca por nomes; confira os pontos no Google Maps">Ver trajeto no Maps ↗</a></div></div></article>`).join('');}
$('more-results').addEventListener('click',e=>{if(e.target.closest('#show-more')){visibleLimit+=10;render(false);}});
$('city').addEventListener('change',()=>{ $('zone').value='';zones();render();});$('zone').addEventListener('change',render);$('section').addEventListener('input',()=>{$('section').value=$('section').value.replace(/\D/g,'');render();});$('filters').addEventListener('submit',e=>{e.preventDefault();render();$('count').scrollIntoView({behavior:'smooth',block:'center'});});$('clear').addEventListener('click',()=>{$('city').value='';$('zone').value='';$('section').value='';zones();render();});
$('results').addEventListener('click',async e=>{const button=e.target.closest('[data-share]');if(!button)return;const g=data[Number(button.dataset.share)],s=$('section').value||String(g.sections[0]);const url=new URL(location.href);url.search=new URLSearchParams({cidade:g.city,zona:g.zone,secao:s}).toString();const text=`Mudança de local de votação em ${pretty(g.city)} — zona ${g.zone}, seção ${s}.\nDe: ${g.from}\nPara: ${g.to}\nFonte: TSE, dados de 17/10/2026 às 20h28. Confirme no e-Título.\n${url}`;try{if(navigator.share)await navigator.share({title:'Confira seu local de votação',text});else{await navigator.clipboard.writeText(text);$('toast').textContent='Informação e link copiados';$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',3000);}}catch(err){if(err.name!=='AbortError'){ $('toast').textContent='Não foi possível compartilhar. Copie o link da página.';$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',5000);}}});
const initial=new URLSearchParams(location.search);if([...$('city').options].some(o=>o.value===initial.get('cidade')))$('city').value=initial.get('cidade');zones();if([...$('zone').options].some(o=>o.value===initial.get('zona')))$('zone').value=initial.get('zona');$('section').value=(initial.get('secao')||'').replace(/\D/g,'').slice(0,5);render();
